/**
 * Sub-issue tree rules: the cycle and depth checks, plus the pure walks
 * (children, descendants, ancestors) the issue service runs over one
 * project's issues. Nothing here touches storage.
 *
 * Must call (do not reimplement): none
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";

/**
 * Refused placement of an issue under a parent. `cycle`: the parent is the
 * issue itself or sits below it. `too_deep`: the issue, or its deepest
 * sub-issue, would land below `MAX_SUB_ISSUE_DEPTH`. For a creation the
 * `issueId` is the parent the new issue was refused under.
 */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: "cycle" | "too_deep",
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself`
        : `Issue ${issueId} would sit deeper than level ${MAX_SUB_ISSUE_DEPTH}`,
    );
    this.name = "IssueHierarchyError";
  }
}

export interface HierarchyNode {
  readonly id: string;
  readonly parentId: string | null;
}

export interface HierarchyIndex<T extends HierarchyNode> {
  readonly byId: ReadonlyMap<string, T>;
  readonly children: ReadonlyMap<string, readonly T[]>;
}

/** Indexes a flat list of issues by id and by parent, keeping input order. */
export function indexHierarchy<T extends HierarchyNode>(
  nodes: readonly T[],
): HierarchyIndex<T> {
  const byId = new Map<string, T>();
  const children = new Map<string, T[]>();
  for (const node of nodes) {
    byId.set(node.id, node);
    if (node.parentId === null) continue;
    const bucket = children.get(node.parentId) ?? [];
    bucket.push(node);
    children.set(node.parentId, bucket);
  }
  return { byId, children };
}

/** Direct children of `id`, in the order they were indexed. */
export function childrenOf<T extends HierarchyNode>(
  index: HierarchyIndex<T>,
  id: string,
): readonly T[] {
  return index.children.get(id) ?? [];
}

/** Ids from `id`'s parent up to the root, nearest first. */
export function ancestorIdsOf<T extends HierarchyNode>(
  index: HierarchyIndex<T>,
  id: string,
): string[] {
  const ids: string[] = [];
  const seen = new Set<string>([id]);
  let cursor = index.byId.get(id)?.parentId ?? null;
  while (cursor !== null && !seen.has(cursor)) {
    seen.add(cursor);
    ids.push(cursor);
    cursor = index.byId.get(cursor)?.parentId ?? null;
  }
  return ids;
}

/** Nodes below `id`, grouped by distance; `id` itself is never included. */
function levelsBelow<T extends HierarchyNode>(
  index: HierarchyIndex<T>,
  id: string,
): T[][] {
  const seen = new Set<string>([id]);
  const levels: T[][] = [];
  let frontier: readonly T[] = childrenOf(index, id);

  while (frontier.length > 0) {
    const level: T[] = [];
    for (const node of frontier) {
      if (seen.has(node.id)) continue;
      seen.add(node.id);
      level.push(node);
    }
    if (level.length === 0) break;
    levels.push(level);
    frontier = level.flatMap((node) => childrenOf(index, node.id));
  }

  return levels;
}

/** Every node below `id` at any depth. */
export function descendantsOf<T extends HierarchyNode>(
  index: HierarchyIndex<T>,
  id: string,
): T[] {
  return levelsBelow(index, id).flat();
}

/** How many levels sit below `id`; 0 for an issue with no sub-issues. */
export function subtreeHeight<T extends HierarchyNode>(
  index: HierarchyIndex<T>,
  id: string,
): number {
  return levelsBelow(index, id).length;
}

/**
 * Throws unless `issueId` (or `null` for an issue not yet created) may sit
 * under `parentId`. The issue's level is its number of ancestors, so under a
 * parent it lands at `ancestors(parent) + 1`, and its whole subtree moves
 * with it: the deepest descendant must still fit within the maximum depth.
 */
export function assertCanPlace<T extends HierarchyNode>(
  index: HierarchyIndex<T>,
  issueId: string | null,
  parentId: string | null,
): void {
  if (parentId === null) return;

  const parentLine = [parentId, ...ancestorIdsOf(index, parentId)];
  if (issueId !== null && parentLine.includes(issueId)) {
    throw new IssueHierarchyError(issueId, "cycle");
  }

  // `parentLine` holds the parent and its ancestors, so its length is the
  // level the placed issue would take.
  const landing = parentLine.length;
  const height = issueId === null ? 0 : subtreeHeight(index, issueId);
  if (landing + height > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId ?? parentId, "too_deep");
  }
}

