/**
 * Every issue of one project, archived ones included, with labels. The
 * sub-issue tree is built from this in memory, so archived rows must stay
 * visible to keep the walks honest.
 */
export async function listProjectIssues(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
      ),
    )
    .orderBy(issues.createdAt, issues.number)
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

export async function setIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

/** Archives the still-live issues among `issueIds`; returns how many changed. */
export async function archiveIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<number> {
  if (issueIds.length === 0) return 0;

  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.id, [...issueIds]),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

