} from "@/types/issue";
import type { Actor } from "@/types/member";

/** Any status outside the closed pair still counts as open. */
function isOpenStatus(status: IssueStatus): boolean {
  return !CLOSED_ISSUE_STATUSES.includes(status);
}

/** Live and still open: the work a parent's completion waits on. */
function isOpenIssue(issue: Issue): boolean {
  return isLive(issue) && isOpenStatus(issue.status);
}

/** Oldest first: creation time, then the per-project number as tie-break. */
function byCreationOrder(a: Issue, b: Issue): number {
  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  return a.number - b.number;
}

/** One project's issues, archived ones included, indexed as a sub-issue tree. */
async function loadProjectTree(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<HierarchyIndex<Issue>> {
  return indexHierarchy(await issueRepo.listProjectIssues(orgId, projectId));
}

/** A parent must be a live issue of the project the tree was loaded for. */
function requireLiveParent(tree: HierarchyIndex<Issue>, parentId: IssueId): Issue {
  const parent = requireFound(tree.byId.get(parentId), "Issue", parentId);
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

/**
 * Tells the parent's assignee once that nothing below the parent is open any
 * more. Reads the tree after the change is stored, so it sees the new state.
 */
async function announceSubIssuesCompleted(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<void> {
  const tree = await loadProjectTree(orgId, projectId);
  const parent = tree.byId.get(parentId);
  if (!parent || !isLive(parent) || parent.assigneeId === null) return;
  if (descendantsOf(tree, parentId).some(isOpenIssue)) return;

  await notify(orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "Sub-issues completed",
    body: `Every sub-issue of issue ${parentId} is now closed`,
    href: `/issues/${parentId}`,
    actorId: actor.userId,
  });
}

