import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("hierarchy");
});

afterAll(() => {
  cleanup();
});

function create(title: string, parentId: Issue["parentId"] = null, status: Issue["status"] = "backlog") {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title, parentId, status }),
  );
}

describe("services/issue-service — sub-issues", () => {
  it("places an issue under a live parent and lists it as a direct sub-issue", async () => {
    const parent = await create("Parent A");
    const child = await create("Child A");

    const moved = await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      parentId: parent.id,
    });

    expect(moved.parentId).toBe(parent.id);
    const subs = await issueService.listSubIssues(tenant.actors.member, tenant.org.id, parent.id);
    expect(subs.map((issue) => issue.id)).toEqual([child.id]);
  });

  it("refuses a parent that is the issue itself or sits below it as a cycle", async () => {
    const root = await create("Cycle root");
    const kid = await create("Cycle kid", root.id);

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: root.id,
        parentId: kid.id,
      }),
    ).rejects.toMatchObject({ reason: "cycle" });
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: root.id,
        parentId: root.id,
      }),
    ).rejects.toBeInstanceOf(IssueHierarchyError);
  });

  it("refuses a move whose deepest sub-issue would land below the maximum depth", async () => {
    const a = await create("Depth a");
    const b = await create("Depth b", a.id);
    const c = await create("Depth c", b.id);
    const d = await create("Depth d", c.id); // level 3, the deepest allowed

    const lone = await create("Depth lone");
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: lone.id,
        parentId: d.id,
      }),
    ).rejects.toMatchObject({ reason: "too_deep" });

    // A subtree of height 1 under a level-2 parent would reach level 4.
    const tall = await create("Depth tall");
    await create("Depth tall kid", tall.id);
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: tall.id,
        parentId: c.id,
      }),
    ).rejects.toMatchObject({ reason: "too_deep" });
  });

  it("refuses a parent from another project or an archived parent", async () => {
    const elsewhere = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Elsewhere",
      slug: "elsewhere",
      key: "ELSE",
      description: null,
      visibility: "org",
      leadId: tenant.userIds.owner,
      color: "#6366f1",
      targetDate: null,
    });
    const foreignParent = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, elsewhere.id, { title: "Foreign parent" }),
    );
    const archivedParent = await create("Archived parent");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedParent.id);

    const child = await create("Needs parent");
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: foreignParent.id,
      }),
    ).rejects.toMatchObject({ code: "not_found" });

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: archivedParent.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("rejects an orgId outside the actor's workspace", async () => {
    const child = await create("Scoped child");
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: "other-org" as Issue["orgId"],
        issueId: child.id,
        parentId: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("creation under a parent is refused without creating anything", async () => {
    const archivedParent = await create("Creation parent");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedParent.id);

    const received: unknown[] = [];
    const off = subscribe("issue.created", (payload) => {
      received.push(payload);
    });

    try {
      await expect(
        create("Refused child", archivedParent.id),
      ).rejects.toBeInstanceOf(AlreadyArchivedError);
      expect(received).toHaveLength(0);
    } finally {
      off();
    }
  });

  it("rolls up every live sub-issue below an issue, at any depth", async () => {
    const top = await create("Rollup top");
    const open = await create("Rollup open", top.id);
    await create("Rollup done", top.id, "done");
    const deep = await create("Rollup deep", open.id, "canceled");
    await create("Rollup deeper", deep.id);
    const gone = await create("Rollup gone", top.id);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, gone.id);

    const rollup = await issueService.getIssueRollup(tenant.actors.member, tenant.org.id, top.id);
    expect(rollup).toEqual({ total: 4, open: 2, closed: 2 });
  });

  it("archiving an issue archives its live sub-issues, each with its own event", async () => {
    const top = await create("Cascade top");
    const mid = await create("Cascade mid", top.id);
    const leaf = await create("Cascade leaf", mid.id);

    const received: string[] = [];
    const off = subscribe("issue.archived", (payload) => {
      received.push(payload.issueId);
    });

    try {
      await issueService.archiveIssue(tenant.actors.member, tenant.org.id, top.id);

      expect(received.sort()).toEqual([top.id, mid.id, leaf.id].sort());
      const stored = await issueRepo.findIssueById(tenant.org.id, leaf.id);
      expect(stored?.archivedAt).not.toBeNull();
    } finally {
      off();
    }
  });

  it("archiving a sub-issue leaves its parent untouched", async () => {
    const parent = await create("Keep parent");
    const child = await create("Drop child", parent.id);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);

    const stored = await issueRepo.findIssueById(tenant.org.id, parent.id);
    expect(stored?.archivedAt).toBeNull();
  });

  it("tells the parent's assignee once when the last open sub-issue closes", async () => {
    const parent = await create("Notify parent");
    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: parent.id,
      assigneeId: tenant.userIds.owner,
    });
    const first = await create("Notify first", parent.id);
    const second = await create("Notify second", parent.id);

    const completedFor = async () =>
      (
        await notificationService.listNotifications(tenant.actors.owner, {
          orgId: tenant.org.id,
          recipientId: tenant.userIds.owner,
          unreadOnly: false,
          kind: ["sub_issues_completed"],
          limit: 100,
          cursor: null,
        })
      ).items.filter((item) => item.href === `/issues/${parent.id}`);

    // The first closing leaves the second one open: nothing is due yet.
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: first.id,
      status: "done",
    });
    expect(await completedFor()).toHaveLength(0);

    // The last open sub-issue closes: the assignee hears once.
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: second.id,
      status: "canceled",
    });
    expect(await completedFor()).toHaveLength(1);

    // Reopening and closing again tells them again.
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: second.id,
      status: "todo",
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: second.id,
      status: "done",
    });
    expect(await completedFor()).toHaveLength(2);
  });
});

